function getIssueUrl(
    repoUrl: string,
    issueNumber: string,
    providerName: string
): string {
    switch (providerName) {
        case "GitHub":
            return `${repoUrl}/issues/${issueNumber}`;
        case "GitLab":
            return `${repoUrl}/-/issues/${issueNumber}`;
        case "Bitbucket":
            return `${repoUrl}/issues/${issueNumber}`;
        default:
            return `${repoUrl}/issues/${issueNumber}`;
    }
}

